arguments.command:
cd /workspace && cat > /tmp/newframe.py <<'PYEOF'
import pathlib
p = pathlib.Path('submission/src/offline/Frame.java')
s = p.read_text()
header = s[:s.index('/** Canonical frame model')]
body = '''/** Canonical frame model: preserves type, order, optional flags and opaque payload bytes. */
final class Frame {
    static final byte[] NO_BYTES = new byte[0];
    static final long[] NO_LONGS = new long[0];

    /** Frame type value. */
    long type;
    /** Body varints, meaning depends on the type. */
    long v1;
    long v2;
    long v3;
    /** ECN counters of an ACK_ECN frame. */
    long e0;
    long e1;
    long e2;
    /** ACK (gap, range) pairs in wire order. */
    long[] pairs = NO_LONGS;
    /** Opaque payload bytes. */
    byte[] data = NO_BYTES;
    /** NEW_CONNECTION_ID bytes. */
    byte[] cid = NO_BYTES;
    byte[] token = NO_BYTES;
    long cidLen;
    /** STREAM flag bits. */
    boolean hasOffset;
    boolean hasLength;
    boolean fin;
    /** Payload offset just after this frame. */
    int end;

    static Frame of(long type) {
        Frame f = new Frame();
        f.type = type;
        return f;
    }

    /** Minimal-varint re-encoding through the repaired codec serializers. */
    static byte[] encode(Frame f) {
        return dto(f).getSerializer().serialize();
    }

    /** Maps the audited frame onto the packet-local codec model. */
    static de.rub.nds.tlsattacker.core.quic.frame.QuicFrame dto(Frame f) {
        int t = (int) f.type;
        de.rub.nds.tlsattacker.core.quic.constants.QuicFrameType kind =
                de.rub.nds.tlsattacker.core.quic.constants.QuicFrameType.getFrameType(f.type);
        switch (t) {
            case 0x00: {
                de.rub.nds.tlsattacker.core.quic.frame.PaddingFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.PaddingFrame();
                frame.setLength(1);
                return frame;
            }
            case 0x01:
                return new de.rub.nds.tlsattacker.core.quic.frame.PingFrame();
            case 0x02:
            case 0x03: {
                de.rub.nds.tlsattacker.core.quic.frame.AckFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.AckFrame(t == 0x03);
                frame.setLargestAcknowledged(f.v1);
                frame.setAckDelay(f.v2);
                frame.setAckRangeCount(f.pairs.length / 2);
                frame.setFirstACKRange(f.v3);
                for (int i = 0; i + 1 < f.pairs.length; i += 2) {
                    frame.getAdditionalRanges().add(new long[] {f.pairs[i], f.pairs[i + 1]});
                }
                if (t == 0x03) {
                    frame.setEct0(f.e0);
                    frame.setEct1(f.e1);
                    frame.setEcnCe(f.e2);
                }
                return frame;
            }
            case 0x04: {
                de.rub.nds.tlsattacker.core.quic.frame.ResetStreamFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.ResetStreamFrame();
                frame.setStreamId(f.v1);
                frame.setApplicationProtocolErrorCode(f.v2);
                frame.setFinalSize(f.v3);
                return frame;
            }
            case 0x05: {
                de.rub.nds.tlsattacker.core.quic.frame.StopSendingFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.StopSendingFrame();
                frame.setStreamId(f.v1);
                frame.setApplicationProtocolErrorCode(f.v2);
                return frame;
            }
            case 0x06: {
                de.rub.nds.tlsattacker.core.quic.frame.CryptoFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.CryptoFrame();
                frame.setOffset(f.v1);
                frame.setLength(f.v2);
                frame.setCryptoData(f.data);
                return frame;
            }
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f: {
                de.rub.nds.tlsattacker.core.quic.frame.StreamFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.StreamFrame(kind);
                frame.setStreamId(f.v1);
                frame.setOffset(f.v2);
                frame.setLength(f.v3);
                frame.setData(f.data);
                return frame;
            }
            case 0x10: {
                de.rub.nds.tlsattacker.core.quic.frame.MaxDataFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.MaxDataFrame();
                frame.setMaximumData(f.v1);
                return frame;
            }
            case 0x11: {
                de.rub.nds.tlsattacker.core.quic.frame.MaxStreamDataFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.MaxStreamDataFrame();
                frame.setStreamId(f.v1);
                frame.setMaximumStreamData(f.v2);
                return frame;
            }
            case 0x12:
            case 0x13: {
                de.rub.nds.tlsattacker.core.quic.frame.MaxStreamsFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.MaxStreamsFrame(t == 0x12);
                frame.setMaximumStreams(f.v1);
                return frame;
            }
            case 0x14: {
                de.rub.nds.tlsattacker.core.quic.frame.DataBlockedFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.DataBlockedFrame();
                frame.setMaximumData(f.v1);
                return frame;
            }
            case 0x15: {
                de.rub.nds.tlsattacker.core.quic.frame.StreamDataBlockedFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.StreamDataBlockedFrame();
                frame.setStreamId(f.v1);
                frame.setMaximumStreamData(f.v2);
                return frame;
            }
            case 0x16:
            case 0x17: {
                de.rub.nds.tlsattacker.core.quic.frame.StreamsBlockedFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.StreamsBlockedFrame(t == 0x16);
                frame.setMaximumStreams(f.v1);
                return frame;
            }
            case 0x18: {
                de.rub.nds.tlsattacker.core.quic.frame.NewConnectionIdFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.NewConnectionIdFrame();
                frame.setSequenceNumber(f.v1);
                frame.setRetirePriorTo(f.v2);
                frame.setConnectionIdLength((int) f.cidLen);
                frame.setConnectionId(f.cid);
                frame.setStatelessResetToken(f.token);
                return frame;
            }
            case 0x19: {
                de.rub.nds.tlsattacker.core.quic.frame.RetireConnectionIdFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.RetireConnectionIdFrame();
                frame.setSequenceNumber(f.v1);
                return frame;
            }
            case 0x1a: {
                de.rub.nds.tlsattacker.core.quic.frame.PathChallengeFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.PathChallengeFrame();
                frame.setData(f.data);
                return frame;
            }
            case 0x1b: {
                de.rub.nds.tlsattacker.core.quic.frame.PathResponseFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.PathResponseFrame();
                frame.setData(f.data);
                return frame;
            }
            case 0x1c: {
                de.rub.nds.tlsattacker.core.quic.frame.ConnectionCloseFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.ConnectionCloseFrame(true);
                frame.setErrorCode(f.v1);
                frame.setTriggerFrameType(f.v2);
                frame.setReasonPhraseLength(f.v3);
                frame.setReasonPhrase(f.data);
                return frame;
            }
            case 0x1d: {
                de.rub.nds.tlsattacker.core.quic.frame.ConnectionCloseFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.ConnectionCloseFrame(false);
                frame.setErrorCode(f.v1);
                frame.setReasonPhraseLength(f.v2);
                frame.setReasonPhrase(f.data);
                return frame;
            }
            case 0x30: {
                de.rub.nds.tlsattacker.core.quic.frame.DatagramFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.DatagramFrame(false);
                frame.setData(f.data);
                return frame;
            }
            case 0x31: {
                de.rub.nds.tlsattacker.core.quic.frame.DatagramFrame frame =
                        new de.rub.nds.tlsattacker.core.quic.frame.DatagramFrame(true);
                frame.setLength(f.v1);
                frame.setData(f.data);
                return frame;
            }
            default:
                throw new IllegalStateException("unsupported frame type " + f.type);
        }
    }
}
'''
p.write_text(header.replace('import de.rub.nds.tlsattacker.core.quic.util.VariableLengthIntegerEncoding;\nimport java.io.ByteArrayOutputStream;\n','')+body)
print('rewritten')
PYEOF
python3 /tmp/newframe.py && python3 build.py submission/src tmp/classes 2>&1 | head -20
